        Long.parseLong(fields[0]),        // timestamp
        fields[1].isEmpty() ? null : fields[1],  // missingInfo
        Long.parseLong(fields[2]),        // jobId
        Integer.parseInt(fields[3]),      // taskIndex
        fields[4].isEmpty() ? -1 : Long.parseLong(fields[4]), // machineId
        Integer.parseInt(fields[5]),      // eventType
        fields[6],                        // user
        Integer.parseInt(fields[7]),      // schedulingClass
        Integer.parseInt(fields[8]),      // priority
        Float.parseFloat(fields[9]),      // cpuRequest
        Float.parseFloat(fields[10]),     // memoryRequest
        Float.parseFloat(fields[11]),     // diskRequest
        Integer.parseInt(fields[12])      // differentMachines
      );

      out.collect(event);

    } catch (NumberFormatException e) {
      System.err.println("Number parsing error in line: " + line);
      // Skip this line
    } catch (Exception e) {
      System.err.println("Unexpected error parsing: " + line);
      // Skip this line
    }
  }
}
