    public static TaskEvent parseTaskEvent(String line) throws IllegalArgumentException {
        if (line == null || line.trim().isEmpty()) {
            return null;
        }

        try {
            String[] fields = line.split(",", -1); // Keep empty fields

            if (fields.length < 13) {
                throw new IllegalArgumentException("Task event has " + fields.length + " fields, expected 13");
            }

            long timestamp = Long.parseLong(fields[0]);
            String missingInfo = fields[1];
            long jobId = Long.parseLong(fields[2]);
            int taskIndex = Integer.parseInt(fields[3]);

            long machineId = -1;
            if (!fields[4].isEmpty()) {
                machineId = Long.parseLong(fields[4]);
            }

            int eventType = Integer.parseInt(fields[5]);
            String user = fields[6];
            int schedulingClass = Integer.parseInt(fields[7]);
            int priority = Integer.parseInt(fields[8]);
            float cpuRequest = Float.parseFloat(fields[9]);
            float memoryRequest = Float.parseFloat(fields[10]);
            float diskRequest = Float.parseFloat(fields[11]);
            int differentMachines = Integer.parseInt(fields[12]);

            return new TaskEvent(timestamp, missingInfo, jobId, taskIndex, machineId,
                    eventType, user, schedulingClass, priority, cpuRequest,
                    memoryRequest, diskRequest, differentMachines);

